  	}
  	if inFlyDotIo() {
  		return FlyDotIo
  	}
  	if inKubernetes() {
  		return Kubernetes
  	}
  	if inDockerDesktop() {
  		return DockerDesktop
  	}
  	if inReplit() {
  		return Replit
  	}
  	if inHomeAssistantAddOn() {
  		return HomeAssistantAddOn
