payload.arguments:
{"cmd":"set -eu
printf '%s\n' '== apparmor event summary by comm/executable/profile/operation =='
perl -ne '
  next unless /apparmor="ALLOWED"/;
  my ($audit) = /audit\([^:]+:([^\)]+)\)/;
  next if defined $audit && $seen{$audit}++;
  my ($profile) = /profile="([^"]+)"/;
  my ($op) = /operation="([^"]+)"/;
  my ($comm) = /comm="([^"]+)"/;
  my ($exe) = /exe="([^"]+)"/;
  my ($name) = /name="([^"]*)"/;
  my ($mask) = /denied_mask="([^"]+)"/;
  my ($cap) = /capname="([^"]+)"/;
  $name = "cap:$cap" if defined $cap;
  $count{join("\t", map { defined($_) ? $_ : "" } ($profile,$comm,$exe,$op,$mask,$name))}++;
  END { for my $key (sort keys %count) { print "$count{$key}\t$key\n" } }
' troubleshoot/apparmor.log | sort -nr | head -120
printf '%s\n' '== unique pids and time ranges for tailscale =='
perl -ne '
  next unless /apparmor="ALLOWED"/ && /profile="usr\.sbin\.tailscaled"/;
  my ($audit) = /audit\(([^:]+):([^\)]+)\)/;
  next if defined $2 && $seen{$2}++;
  my ($pid)=/pid=(\d+)/; my ($comm)=/comm="([^"]+)"/; my ($op)=/operation="([^"]+)"/; my ($name)=/name="([^"]*)"/; my ($cap)=/capname="([^"]+)"/;
  $name = "cap:$cap" if defined $cap;
  my $key=join("\t",map {defined($_)?$_:""}($pid,$comm));
  $first{$key}//=$audit; $last{$key}=$audit; $ops{$key}{$op}++; $samples{$key}{$name}=1 if defined $name;
  END { for my $key (sort keys %ops) { my @op=map{"$_=$ops{$key}{$_}"}sort keys %{$ops{$key}}; my @s=(sort keys %{$samples{$key}})[0..(($#{[sort keys %{$samples{$key}}]}<4)?$#{[sort keys %{$samples{$key}}]}:4)]; print "$key\t$first{$key}\t$last{$key}\t",join(",",@op),"\t",join(" | ",@s),"\n"; } }
' troubleshoot/apparmor.log
printf '%s\n' '== non-directory Tailscale records =='
perl -ne '
  next unless /apparmor="ALLOWED"/ && /profile="usr\.sbin\.tailscaled"/;
  my ($audit) = /audit\([^:]+:([^\)]+)\)/; next if defined $audit && $seen{$audit}++;
  my ($op)=/operation="([^"]+)"/; my ($name)=/name="([^"]*)"/; my ($ft)=/fsuid=(\d+)/; my ($mask)=/denied_mask="([^"]+)"/; my ($comm)=/comm="([^"]+)"/; my ($info)=/info="([^"]+)"/; my ($target)=/target="([^"]+)"/; my ($cap)=/capname="([^"]+)"/;
  next if defined($name) && $name =~ m{/$} && $op eq "open";
  print join("\t",map{defined($_)?$_:""}($comm,$op,$mask,$name,$cap,$info,$target)),"\n";
