printf '1..%s\n' "$TEST_COUNT"

if [ -d "$MODULE_ROOT/WhisperMode" ] &&
   [ ! -e "$MODULE_ROOT/Whisper" ] &&
   [ ! -L "$MODULE_ROOT/Whisper" ]; then
  pass "WhisperMode is the only installed Whisper Perl namespace"
