 fi

+cat >"$TMP_DIR/runtime-behavior.pl" <<'EOF'
+use strict;
+use warnings;
+
+use WhisperMode::Recorder;
+use WhisperMode::Systemd;
+
+{
+    package TestSystemd;
+    our @ISA = ('WhisperMode::Systemd');
+    our @calls;
+
+    sub _run {
+        my ($self, @arguments) = @_;
+        push @calls, join("\0", @arguments);
+        return 0;
+    }
+}
+
+my $systemd = TestSystemd->new();
+$systemd->start_transcription();
+@TestSystemd::calls == 1
+    && $TestSystemd::calls[0] eq "--no-block\0start\0whisper-transcribe.service"
+    or die "transcription was not started asynchronously\n";
+
+{
+    package TestStopSystemd;
+    sub stop_recording { die "stop failed\n"; }
+
+    package TestAudio;
+    sub new { return bless { mute_values => [] }, shift; }
+    sub set_default_source_muted {
+        my ($self, $value) = @_;
+        push @{$self->{mute_values}}, $value;
+        return;
+    }
+
+    package TestState;
+    sub read { return undef; }
+
+    package TestArtifacts;
