   121	
   122	    -f $self->mode_config() && !-l $self->mode_config()
   123	        or die "managed AppArmor mode configuration must be a regular non-symlink file\n";
   124	    my @stat = stat $self->mode_config();
   125	    @stat or die "cannot inspect managed AppArmor mode configuration\n";
