   135	sub _read_small_file {
   136	    my ($self, $path, $limit, $label) = @_;
   137	
   138	    open my $fh, '<', $path or die "cannot read $label: $!\n";
   139	    local $/;
   140	    my $content = <$fh>;
   141	    close $fh or die "cannot close $label: $!\n";
