   147	sub _validate_executable {
   148	    my ($self, $requested) = @_;
   149	
   150	    defined($requested) && $requested =~ m{\A/}
   151	        or die "AppArmor executable path must be absolute\n";
   152	    $requested !~ /[\r\n]/
   153	        or die "AppArmor executable path cannot contain newlines\n";
   154	    length($requested) <= $self->maximum_executable_path_bytes()
   155	        or die "AppArmor executable path exceeds " . $self->maximum_executable_path_bytes() . " bytes\n";
   156	    my $readlink = $self->_program('readlink');
   157	    my ($status, $resolved) = $self->command()->capture(
   158	        argv => [$readlink, '-f', '--', $requested],
   159	    );
   160	    $status == 0
   161	        or die "unable to resolve AppArmor executable path: $requested\n";
   162	    $resolved =~ s/[\r\n]+\z//;
   163	    -f $resolved && -x $resolved
   164	        or die "AppArmor executable path is not an executable regular file: $resolved\n";
   165	    return $resolved;
